package tui

import (
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/n-orlov/deck/internal/config"
)

// This file is task 013's `,` settings full-screen takeover skeleton (SPEC
// §11.5): a category list on the left, the selected category's field list
// on the right, both generated by walking internal/config.Schema rather
// than a second, hand-written field set (the exact defect requirement 22
// exists to catch). Navigation beyond "open, close" (tab/left/right/up/
// down, `/` fuzzy search), per-kind rendering, save/discard and the env-
// override label are tasks 014-018; this file only lays the frame down and
// proves it walks the schema and stays inside the terminal's budget.

// settingsCategory groups the schema fields that share one Field.Section
// under one human category name for the takeover's left-hand list.
type settingsCategory struct {
	Name    string
	Section string
	Fields  []config.Field
}

// settingsCategoryName maps a schema Field.Section to the takeover's
// human category label. Recorded here (rather than left to whichever task
// first needed a name) since task 013's notes flagged this as a decision
// to make and record: "" (config.toml's own top level) is "General", "ui"
// is "UI", "env" is "Environment" — matching config.toml's own section
// names for anything not top-level, since that is what a user editing the
// file by hand already sees.
func settingsCategoryName(section string) string {
	switch section {
	case "":
		return "General"
	case "ui":
		return "UI"
	case "env":
		return "Environment"
	default:
		return strings.ToUpper(section[:1]) + section[1:]
	}
}

// settingsCategories walks config.Schema exactly once, grouping fields by
// Section in the order each section is first seen (schema.go already lists
// "", then "ui", then "env" contiguously, but this does not assume that —
// a schema field reordered or a new section inserted between others still
// groups correctly). This is the one and only place tasks 013-018 read the
// schema to build the takeover's category/field lists: neither list is
// ever hand-written alongside it.
func settingsCategories() []settingsCategory {
	var categories []settingsCategory
	indexBySection := map[string]int{}
	for _, field := range config.Schema {
		i, ok := indexBySection[field.Section]
		if !ok {
			i = len(categories)
			indexBySection[field.Section] = i
			categories = append(categories, settingsCategory{
				Name:    settingsCategoryName(field.Section),
				Section: field.Section,
			})
		}
		categories[i].Fields = append(categories[i].Fields, field)
	}
	return categories
}

// settingsFieldLabel renders a schema Field's human label for the
// takeover's field list: the key's underscore-separated words, each
// capitalised ("recent_cwd_limit" -> "Recent Cwd Limit"). The [env] table
// field (Key == "", Section == "env") has no key to derive a label from —
// it is named for what it is instead.
func settingsFieldLabel(f config.Field) string {
	if f.Key == "" {
		return "Environment Variables"
	}
	words := strings.Split(f.Key, "_")
	for i, w := range words {
		if w == "" {
			continue
		}
		words[i] = strings.ToUpper(w[:1]) + w[1:]
	}
	return strings.Join(words, " ")
}

// updateSettings handles key input while the takeover is open. Task 013
// only wires the takeover's own on/off switch (esc closes, mirroring every
// other overlay's esc-closes default before task 016 adds the discard
// prompt for unsaved changes); every other key is a no-op until task 014
// adds navigation and search.
func (m Model) updateSettings(msg tea.KeyMsg) (Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.settingsOpen = false
	}
	return m, nil
}

// settingsCategoryWidth picks the left category panel's width the same way
// ComputeLayout picks the sidebar's: a fraction of the total width, clamped
// to a floor that keeps every category name legible and a ceiling that
// leaves the field list (the panel that actually carries the field's
// description text, task 015) the majority of the screen.
func settingsCategoryWidth(width int) int {
	w := width / 3
	const floor, ceil = 20, 30
	if w < floor {
		w = floor
	}
	if w > ceil {
		w = ceil
	}
	if width-w < floor {
		w = width - floor
	}
	if w < 1 {
		w = 1
	}
	return w
}

// settingsView renders the full-screen takeover: a category list panel and
// a field list panel sharing one seam, reusing the exact border-drawing
// helpers the main side-by-side frame already uses (panel.go's
// sidebarTopLine/sidebarContentLine/sidebarBottomLine for the left panel,
// previewTopLine/previewContentLine/previewBottomLine with seam=true for
// the right) rather than a second box-drawing implementation — SPEC
// requirement 16's "bordered like every other panel, dialog and overlay"
// with one geometry, not two.
func (m Model) settingsView() string {
	width, height := m.frameSize()
	leftWidth := settingsCategoryWidth(width)
	rightWidth := width - leftWidth
	// One row for the top border, one for the bottom border, one for the
	// footer line below the frame (mirroring mainView's own footerLine).
	contentRows := height - 3
	if contentRows < 0 {
		contentRows = 0
	}

	categories := settingsCategories()
	leftLines := make([]string, len(categories))
	for i, cat := range categories {
		marker := "  "
		if i == m.settingsCategoryIndex {
			marker = "> "
		}
		leftLines[i] = marker + cat.Name
	}
	leftLines = fitLines(leftLines, contentRows)

	var rightLines []string
	if m.settingsCategoryIndex >= 0 && m.settingsCategoryIndex < len(categories) {
		fields := categories[m.settingsCategoryIndex].Fields
		rightLines = make([]string, len(fields))
		for i, f := range fields {
			marker := "  "
			if i == m.settingsFieldIndex {
				marker = "> "
			}
			rightLines[i] = marker + settingsFieldLabel(f)
		}
	}
	rightLines = fitLines(rightLines, contentRows)

	lines := make([]string, 0, height)
	lines = append(lines, m.sidebarTopLine(leftWidth, "Categories")+m.previewTopLine(rightWidth, "Fields", true))
	for i := 0; i < contentRows; i++ {
		lines = append(lines, m.sidebarContentLine(leftWidth, leftLines[i])+m.previewContentLine(rightWidth, rightLines[i]))
	}
	lines = append(lines, m.sidebarBottomLine(leftWidth)+m.previewBottomLine(rightWidth, true))
	lines = append(lines, m.settingsFooterLine())
	return strings.Join(lines, "\n")
}

// settingsFooterLine states only the one key task 013 actually binds
// (esc). Naming a key the takeover does not yet act on here would be the
// same "advertises a key it doesn't grant" defect the §11.4 dialog
// contract (task 029) forbids for the five dialogs; tasks 014/016 extend
// this line as navigation, search and save land.
func (m Model) settingsFooterLine() string {
	return "esc close"
}
